  subroutine check_vegetation_carbon_flux(this, label, nmiss)
    type(vegetation_carbon_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_vegetation_nutrient_flux(this%core, trim(label)//'%core', nmiss)
    if (associated(this%m_gresp_storage_to_litter)) call dd_miss(acc_is_present(this%m_gresp_storage_to_litter), &
         label, 'm_gresp_storage_to_litter', nmiss)
    if (associated(this%m_gresp_xfer_to_litter)) call dd_miss(acc_is_present(this%m_gresp_xfer_to_litter), label, &
         'm_gresp_xfer_to_litter', nmiss)
    if (.not. use_fates .and. use_cn) then
       if (associated(this%hrv_gresp_storage_to_litter)) call dd_miss(acc_is_present(this%hrv_gresp_storage_to_litter), &
            label, 'hrv_gresp_storage_to_litter', nmiss)
    end if
    if (.not. use_fates .and. use_cn) then
       if (associated(this%hrv_gresp_xfer_to_litter)) call dd_miss(acc_is_present(this%hrv_gresp_xfer_to_litter), label, &
            'hrv_gresp_xfer_to_litter', nmiss)
    end if
    if (.not. use_fates .and. use_cn) then
       if (associated(this%hrv_xsmrpool_to_atm)) call dd_miss(acc_is_present(this%hrv_xsmrpool_to_atm), label, &
            'hrv_xsmrpool_to_atm', nmiss)
    end if
    if (associated(this%m_gresp_storage_to_fire)) call dd_miss(acc_is_present(this%m_gresp_storage_to_fire), label, &
         'm_gresp_storage_to_fire', nmiss)
    if (associated(this%m_gresp_xfer_to_fire)) call dd_miss(acc_is_present(this%m_gresp_xfer_to_fire), label, &
         'm_gresp_xfer_to_fire', nmiss)
    if (associated(this%m_gresp_storage_to_litter_fire)) call dd_miss(acc_is_present(this%m_gresp_storage_to_litter_fire), &
         label, 'm_gresp_storage_to_litter_fire', nmiss)
    if (associated(this%m_gresp_xfer_to_litter_fire)) call dd_miss(acc_is_present(this%m_gresp_xfer_to_litter_fire), &
         label, 'm_gresp_xfer_to_litter_fire', nmiss)
    if (associated(this%leaf_mr)) call dd_miss(acc_is_present(this%leaf_mr), label, 'leaf_mr', nmiss)
    if (associated(this%froot_mr)) call dd_miss(acc_is_present(this%froot_mr), label, 'froot_mr', nmiss)
    if (associated(this%livestem_mr)) call dd_miss(acc_is_present(this%livestem_mr), label, 'livestem_mr', nmiss)
    if (associated(this%livecroot_mr)) call dd_miss(acc_is_present(this%livecroot_mr), label, 'livecroot_mr', nmiss)
    if (.not. use_fates .and. use_cn) then
       if (associated(this%grain_mr)) call dd_miss(acc_is_present(this%grain_mr), label, 'grain_mr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%leaf_curmr)) call dd_miss(acc_is_present(this%leaf_curmr), label, 'leaf_curmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%froot_curmr)) call dd_miss(acc_is_present(this%froot_curmr), label, 'froot_curmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%livestem_curmr)) call dd_miss(acc_is_present(this%livestem_curmr), label, 'livestem_curmr', &
            nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%livecroot_curmr)) call dd_miss(acc_is_present(this%livecroot_curmr), label, &
            'livecroot_curmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%grain_curmr)) call dd_miss(acc_is_present(this%grain_curmr), label, 'grain_curmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%leaf_xsmr)) call dd_miss(acc_is_present(this%leaf_xsmr), label, 'leaf_xsmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%froot_xsmr)) call dd_miss(acc_is_present(this%froot_xsmr), label, 'froot_xsmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%livestem_xsmr)) call dd_miss(acc_is_present(this%livestem_xsmr), label, 'livestem_xsmr', nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%livecroot_xsmr)) call dd_miss(acc_is_present(this%livecroot_xsmr), label, 'livecroot_xsmr', &
            nmiss)
    end if
    if (use_fates .or. use_cn) then
       if (associated(this%grain_xsmr)) call dd_miss(acc_is_present(this%grain_xsmr), label, 'grain_xsmr', nmiss)
    end if
    if (associated(this%xr)) call dd_miss(acc_is_present(this%xr), label, 'xr', nmiss)
    if (associated(this%psnsun_to_cpool)) call dd_miss(acc_is_present(this%psnsun_to_cpool), label, &
         'psnsun_to_cpool', nmiss)
    if (associated(this%psnshade_to_cpool)) call dd_miss(acc_is_present(this%psnshade_to_cpool), label, &
         'psnshade_to_cpool', nmiss)
    if (use_fates .or. use_cn) then
       if (associated(this%cpool_to_xsmrpool)) call dd_miss(acc_is_present(this%cpool_to_xsmrpool), label, &
            'cpool_to_xsmrpool', nmiss)
    end if
    if (associated(this%cpool_to_gresp_storage)) call dd_miss(acc_is_present(this%cpool_to_gresp_storage), label, &
         'cpool_to_gresp_storage', nmiss)
    if (use_fates .or. use_cn) then
       if (associated(this%xsmrpool_to_atm)) call dd_miss(acc_is_present(this%xsmrpool_to_atm), label, &
            'xsmrpool_to_atm', nmiss)
    end if
    if (associated(this%cpool_leaf_gr)) call dd_miss(acc_is_present(this%cpool_leaf_gr), label, 'cpool_leaf_gr', nmiss)
    if (associated(this%cpool_leaf_storage_gr)) call dd_miss(acc_is_present(this%cpool_leaf_storage_gr), label, &
         'cpool_leaf_storage_gr', nmiss)
    if (associated(this%transfer_leaf_gr)) call dd_miss(acc_is_present(this%transfer_leaf_gr), label, &
         'transfer_leaf_gr', nmiss)
    if (associated(this%cpool_froot_gr)) call dd_miss(acc_is_present(this%cpool_froot_gr), label, 'cpool_froot_gr', &
         nmiss)
    if (associated(this%cpool_froot_storage_gr)) call dd_miss(acc_is_present(this%cpool_froot_storage_gr), label, &
         'cpool_froot_storage_gr', nmiss)
    if (associated(this%transfer_froot_gr)) call dd_miss(acc_is_present(this%transfer_froot_gr), label, &
         'transfer_froot_gr', nmiss)
    if (associated(this%cpool_livestem_gr)) call dd_miss(acc_is_present(this%cpool_livestem_gr), label, &
