  subroutine check_vegetation_nitrogen_flux(this, label, nmiss)
    type(vegetation_nitrogen_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_vegetation_uptake_flux(this%uptake, trim(label)//'%uptake', nmiss)
