  subroutine update_vegetation_phosphorus_flux(this, to_device)
    type(vegetation_phosphorus_flux), intent(inout), target :: this
    logical, intent(in) :: to_device
    integer :: i_
#ifdef _OPENACC
    call update_vegetation_uptake_flux(this%uptake, to_device)
    call update_vegetation_retrans_flux(this%retrans, to_device)
    call update_vegetation_nutrient_flux(this%core, to_device)
    if (associated(this%fert_p)) then
       !$acc update device(this%fert_p) if(to_device)
       !$acc update self(this%fert_p) if(.not. to_device)
    end if
    if (associated(this%fert_p_counter)) then
       !$acc update device(this%fert_p_counter) if(to_device)
       !$acc update self(this%fert_p_counter) if(.not. to_device)
    end if
    if ((.not. use_fates .and. use_cn) .or. (use_elm_interface .and. use_pflotran .and. use_fates)) then
       if (associated(this%biochem_pmin_to_plant)) then
          !$acc update device(this%biochem_pmin_to_plant) if(to_device)
          !$acc update self(this%biochem_pmin_to_plant) if(.not. to_device)
       end if
    end if
    if (associated(this%dwt_seedp_to_ppool)) then
       !$acc update device(this%dwt_seedp_to_ppool) if(to_device)
       !$acc update self(this%dwt_seedp_to_ppool) if(.not. to_device)
    end if
    if (associated(this%sminp_to_plant_trans)) then
       !$acc update device(this%sminp_to_plant_trans) if(to_device)
       !$acc update self(this%sminp_to_plant_trans) if(.not. to_device)
    end if
    if (associated(this%gap_ploss_litter)) then
       !$acc update device(this%gap_ploss_litter) if(to_device)
       !$acc update self(this%gap_ploss_litter) if(.not. to_device)
    end if
    if (associated(this%fire_ploss_litter)) then
       !$acc update device(this%fire_ploss_litter) if(to_device)
       !$acc update self(this%fire_ploss_litter) if(.not. to_device)
    end if
    if (associated(this%hrv_ploss_litter)) then
       !$acc update device(this%hrv_ploss_litter) if(to_device)
       !$acc update self(this%hrv_ploss_litter) if(.not. to_device)
    end if
    if (associated(this%sen_ploss_litter)) then
       !$acc update device(this%sen_ploss_litter) if(to_device)
