  subroutine check_vegetation_phosphorus_flux(this, label, nmiss)
    type(vegetation_phosphorus_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    call check_vegetation_uptake_flux(this%uptake, trim(label)//'%uptake', nmiss)
    call check_vegetation_retrans_flux(this%retrans, trim(label)//'%retrans', nmiss)
    call check_vegetation_nutrient_flux(this%core, trim(label)//'%core', nmiss)
    if (associated(this%fert_p)) call dd_miss(acc_is_present(this%fert_p), label, 'fert_p', nmiss)
    if (associated(this%fert_p_counter)) call dd_miss(acc_is_present(this%fert_p_counter), label, 'fert_p_counter', &
         nmiss)
    if ((.not. use_fates .and. use_cn) .or. (use_elm_interface .and. use_pflotran .and. use_fates)) then
       if (associated(this%biochem_pmin_to_plant)) call dd_miss(acc_is_present(this%biochem_pmin_to_plant), label, &
            'biochem_pmin_to_plant', nmiss)
    end if
    if (associated(this%dwt_seedp_to_ppool)) call dd_miss(acc_is_present(this%dwt_seedp_to_ppool), label, &
         'dwt_seedp_to_ppool', nmiss)
    if (associated(this%sminp_to_plant_trans)) call dd_miss(acc_is_present(this%sminp_to_plant_trans), label, &
         'sminp_to_plant_trans', nmiss)
    if (associated(this%gap_ploss_litter)) call dd_miss(acc_is_present(this%gap_ploss_litter), label, &
         'gap_ploss_litter', nmiss)
    if (associated(this%fire_ploss_litter)) call dd_miss(acc_is_present(this%fire_ploss_litter), label, &
         'fire_ploss_litter', nmiss)
    if (associated(this%hrv_ploss_litter)) call dd_miss(acc_is_present(this%hrv_ploss_litter), label, &
         'hrv_ploss_litter', nmiss)
    if (associated(this%sen_ploss_litter)) call dd_miss(acc_is_present(this%sen_ploss_litter), label, &
         'sen_ploss_litter', nmiss)
    if (associated(this%uptake%plant_demand)) call dd_miss(acc_is_present(this%uptake%plant_demand), label, &
         'uptake%plant_demand', nmiss)
    if (associated(this%uptake%plant_demand_vr)) call dd_miss(acc_is_present(this%uptake%plant_demand_vr), label, &
         'uptake%plant_demand_vr', nmiss)
    if (associated(this%uptake%smin_to_plant)) call dd_miss(acc_is_present(this%uptake%smin_to_plant), label, &
         'uptake%smin_to_plant', nmiss)
    if (associated(this%uptake%smin_to_pool)) call dd_miss(acc_is_present(this%uptake%smin_to_pool), label, &
         'uptake%smin_to_pool', nmiss)
    if (associated(this%uptake%supplement_to_plant)) call dd_miss(acc_is_present(this%uptake%supplement_to_plant), &
         label, 'uptake%supplement_to_plant', nmiss)
    if (associated(this%uptake%pool_deploy)) call dd_miss(acc_is_present(this%uptake%pool_deploy), label, &
         'uptake%pool_deploy', nmiss)
    if (associated(this%retrans%m_retrans_to_litter)) call dd_miss(acc_is_present(this%retrans%m_retrans_to_litter), &
         label, 'retrans%m_retrans_to_litter', nmiss)
    if (associated(this%retrans%hrv_retrans_to_litter)) call dd_miss(acc_is_present(this%retrans%hrv_retrans_to_litter), &
         label, 'retrans%hrv_retrans_to_litter', nmiss)
    if (associated(this%retrans%m_retrans_to_fire)) call dd_miss(acc_is_present(this%retrans%m_retrans_to_fire), &
         label, 'retrans%m_retrans_to_fire', nmiss)
    if (associated(this%retrans%m_retrans_to_litter_fire)) call dd_miss(acc_is_present(this%retrans%m_retrans_to_litter_fire), &
         label, 'retrans%m_retrans_to_litter_fire', nmiss)
    if (associated(this%retrans%leaf_to_retrans)) call dd_miss(acc_is_present(this%retrans%leaf_to_retrans), label, &
         'retrans%leaf_to_retrans', nmiss)
    if (associated(this%retrans%froot_to_retrans)) call dd_miss(acc_is_present(this%retrans%froot_to_retrans), label, &
         'retrans%froot_to_retrans', nmiss)
    if (associated(this%retrans%retrans_to_pool)) call dd_miss(acc_is_present(this%retrans%retrans_to_pool), label, &
         'retrans%retrans_to_pool', nmiss)
    if (associated(this%retrans%livestem_to_retrans)) call dd_miss(acc_is_present(this%retrans%livestem_to_retrans), &
         label, 'retrans%livestem_to_retrans', nmiss)
    if (associated(this%retrans%livecroot_to_retrans)) call dd_miss(acc_is_present(this%retrans%livecroot_to_retrans), &
         label, 'retrans%livecroot_to_retrans', nmiss)
    if (associated(this%retrans%avail_retrans)) call dd_miss(acc_is_present(this%retrans%avail_retrans), label, &
         'retrans%avail_retrans', nmiss)
    if (associated(this%core%m_leaf_to_litter)) call dd_miss(acc_is_present(this%core%m_leaf_to_litter), label, &
         'core%m_leaf_to_litter', nmiss)
    if (associated(this%core%m_leaf_storage_to_litter)) call dd_miss(acc_is_present(this%core%m_leaf_storage_to_litter), &
         label, 'core%m_leaf_storage_to_litter', nmiss)
    if (associated(this%core%m_leaf_xfer_to_litter)) call dd_miss(acc_is_present(this%core%m_leaf_xfer_to_litter), &
         label, 'core%m_leaf_xfer_to_litter', nmiss)
    if (associated(this%core%m_froot_to_litter)) call dd_miss(acc_is_present(this%core%m_froot_to_litter), label, &
         'core%m_froot_to_litter', nmiss)
