         label, 'core%m_livestem_to_litter', nmiss)
    if (associated(this%core%m_livestem_storage_to_litter)) call dd_miss(acc_is_present(this%core%m_livestem_storage_to_litter), &
         label, 'core%m_livestem_storage_to_litter', nmiss)
    if (associated(this%core%m_livestem_xfer_to_litter)) call dd_miss(acc_is_present(this%core%m_livestem_xfer_to_litter), &
         label, 'core%m_livestem_xfer_to_litter', nmiss)
    if (associated(this%core%m_deadstem_to_litter)) call dd_miss(acc_is_present(this%core%m_deadstem_to_litter), &
         label, 'core%m_deadstem_to_litter', nmiss)
    if (associated(this%core%m_deadstem_storage_to_litter)) call dd_miss(acc_is_present(this%core%m_deadstem_storage_to_litter), &
