    if (associated(this%core%m_livecroot_storage_to_litter)) call dd_miss(acc_is_present(this%core%m_livecroot_storage_to_litter), &
         label, 'core%m_livecroot_storage_to_litter', nmiss)
    if (associated(this%core%m_livecroot_xfer_to_litter)) call dd_miss(acc_is_present(this%core%m_livecroot_xfer_to_litter), &
         label, 'core%m_livecroot_xfer_to_litter', nmiss)
    if (associated(this%core%m_deadcroot_to_litter)) call dd_miss(acc_is_present(this%core%m_deadcroot_to_litter), &
         label, 'core%m_deadcroot_to_litter', nmiss)
    if (associated(this%core%m_deadcroot_storage_to_litter)) call dd_miss(acc_is_present(this%core%m_deadcroot_storage_to_litter), &
         label, 'core%m_deadcroot_storage_to_litter', nmiss)
    if (associated(this%core%m_deadcroot_xfer_to_litter)) call dd_miss(acc_is_present(this%core%m_deadcroot_xfer_to_litter), &
         label, 'core%m_deadcroot_xfer_to_litter', nmiss)
    if (associated(this%core%m_pool_to_litter)) call dd_miss(acc_is_present(this%core%m_pool_to_litter), label, &
