  ! ---- vegetation_phosphorus_state (vegetationstatetypes)

  subroutine deepcopy_vegetation_phosphorus_state(this)
    type(vegetation_phosphorus_state), intent(inout), target :: this
    integer :: i_
#ifdef _OPENACC
    call deepcopy_vegetation_retrans_state(this%retrans)
    call deepcopy_vegetation_nutrient_state(this%core)
    if (associated(this%plant_p_buffer)) then
       !$acc enter data copyin(this%plant_p_buffer)
    end if
    if (associated(this%retrans%pool)) then
       !$acc enter data copyin(this%retrans%pool)
    end if
    !$acc update device(this%core%species)
    if (associated(this%core%leaf)) then
       !$acc enter data copyin(this%core%leaf)
    end if
    if (associated(this%core%leaf_storage)) then
       !$acc enter data copyin(this%core%leaf_storage)
    end if
    if (associated(this%core%leaf_xfer)) then
       !$acc enter data copyin(this%core%leaf_xfer)
