       !$acc enter data copyin(this%plant_demand)
    end if
    if (associated(this%plant_demand_vr)) then
       !$acc enter data copyin(this%plant_demand_vr)
    end if
    if (associated(this%smin_to_plant)) then
       !$acc enter data copyin(this%smin_to_plant)
    end if
    if (associated(this%smin_to_pool)) then
       !$acc enter data copyin(this%smin_to_pool)
    end if
    if (associated(this%supplement_to_plant)) then
       !$acc enter data copyin(this%supplement_to_plant)
    end if
    if (associated(this%pool_deploy)) then
       !$acc enter data copyin(this%pool_deploy)
    end if
#endif
  end subroutine deepcopy_vegetation_uptake_flux

  subroutine update_vegetation_uptake_flux(this, to_device)
    type(vegetation_uptake_flux), intent(inout), target :: this
    logical, intent(in) :: to_device
    integer :: i_
#ifdef _OPENACC
    if (associated(this%plant_demand)) then
       !$acc update device(this%plant_demand) if(to_device)
       !$acc update self(this%plant_demand) if(.not. to_device)
    end if
    if (associated(this%plant_demand_vr)) then
       !$acc update device(this%plant_demand_vr) if(to_device)
       !$acc update self(this%plant_demand_vr) if(.not. to_device)
    end if
    if (associated(this%smin_to_plant)) then
       !$acc update device(this%smin_to_plant) if(to_device)
       !$acc update self(this%smin_to_plant) if(.not. to_device)
    end if
    if (associated(this%smin_to_pool)) then
       !$acc update device(this%smin_to_pool) if(to_device)
       !$acc update self(this%smin_to_pool) if(.not. to_device)
    end if
    if (associated(this%supplement_to_plant)) then
       !$acc update device(this%supplement_to_plant) if(to_device)
       !$acc update self(this%supplement_to_plant) if(.not. to_device)
    end if
    if (associated(this%pool_deploy)) then
       !$acc update device(this%pool_deploy) if(to_device)
       !$acc update self(this%pool_deploy) if(.not. to_device)
    end if
#endif
  end subroutine update_vegetation_uptake_flux

  subroutine check_vegetation_uptake_flux(this, label, nmiss)
    type(vegetation_uptake_flux), intent(in), target :: this
    character(len=*), intent(in) :: label
    integer, intent(inout) :: nmiss
    integer :: i_
#ifdef _OPENACC
    if (associated(this%plant_demand)) call dd_miss(acc_is_present(this%plant_demand), label, 'plant_demand', nmiss)
    if (associated(this%plant_demand_vr)) call dd_miss(acc_is_present(this%plant_demand_vr), label, &
         'plant_demand_vr', nmiss)
    if (associated(this%smin_to_plant)) call dd_miss(acc_is_present(this%smin_to_plant), label, 'smin_to_plant', nmiss)
    if (associated(this%smin_to_pool)) call dd_miss(acc_is_present(this%smin_to_pool), label, 'smin_to_pool', nmiss)
    if (associated(this%supplement_to_plant)) call dd_miss(acc_is_present(this%supplement_to_plant), label, &
         'supplement_to_plant', nmiss)
    if (associated(this%pool_deploy)) call dd_miss(acc_is_present(this%pool_deploy), label, 'pool_deploy', nmiss)
#endif
  end subroutine check_vegetation_uptake_flux

  subroutine dd_miss(present_, label, comp, nmiss)
    ! count (and report the first 50 of) the arrays not present on the device
    logical, intent(in) :: present_
    character(len=*), intent(in) :: label, comp
    integer, intent(inout) :: nmiss
    if (present_) return
    nmiss = nmiss + 1
    if (nmiss <= 50) write(iulog,*) 'elm_device: not present: ', trim(label)//'%'//comp
  end subroutine dd_miss

end module DeepCopyVegNutrientMod
